// Package mock provides an in-memory simulation of the FreeBSD network
// stack that understands the subset of ifconfig/route/sysctl commands
// generated by the planner. It is used by unit tests, API tests, the
// Playwright e2e suite and `bsdswitchd -sim` for UI development on any OS.
package mock

import (
	"context"
	"fmt"
	"math/rand"
	"os"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/Lukas0923xcv/freebsdswitch/internal/backend"
	"github.com/Lukas0923xcv/freebsdswitch/internal/config"
	"github.com/Lukas0923xcv/freebsdswitch/internal/state"
)

// Sim is a simulated kernel.
type Sim struct {
	mu         sync.Mutex
	ifs        map[string]*state.Interface
	order      []string
	macs       map[string][]state.MACEntry // per bridge
	sysctl     map[string]string
	routes     backend.Routes
	files      map[string][]byte
	counters   map[string]*backend.Counters
	start      time.Time
	hostname   string
	laggMember map[string]string

	// Log records every executed command.
	Log []string
	// FailOn makes Run fail for commands matching the regexp.
	FailOn *regexp.Regexp
	// OnRun is called for each executed command (after FailOn).
	OnRun func(op backend.Op)
	// Traffic enables synthetic counter growth on link-up interfaces.
	Traffic bool
}

// NIC describes a simulated physical NIC.
type NIC struct {
	Name   string
	Driver string
	Link   bool
	Speeds []int // supported fixed speeds, nil = virtio-like autoselect only
}

// New returns a simulator with the given NICs plus lo0.
func New(nics ...NIC) *Sim {
	s := &Sim{
		ifs:        map[string]*state.Interface{},
		macs:       map[string][]state.MACEntry{},
		sysctl:     map[string]string{},
		files:      map[string][]byte{},
		counters:   map[string]*backend.Counters{},
		start:      time.Now(),
		hostname:   "bsdswitch",
		laggMember: map[string]string{},
	}
	for _, k := range backend.SysctlsOfInterest {
		s.sysctl[k] = "0"
	}
	s.sysctl["net.link.bridge.pfil_member"] = "1"
	s.sysctl["net.link.bridge.pfil_bridge"] = "0"
	s.sysctl["net.link.bridge.log_mac_flap"] = "1"
	s.add(&state.Interface{Name: "lo0", Driver: "lo", Flags: []string{"UP", "LOOPBACK", "RUNNING", "MULTICAST"}, MTU: 16384, Cloned: true, IPv4: []string{"127.0.0.1/8"}})
	for i, n := range nics {
		drv := n.Driver
		if drv == "" {
			drv = strings.TrimRight(n.Name, "0123456789")
		}
		ifc := &state.Interface{
			Name: n.Name, Driver: drv, DriverUnit: n.Name, MTU: 1500,
			Flags:          []string{"BROADCAST", "SIMPLEX", "MULTICAST"},
			MAC:            fmt.Sprintf("bc:24:11:aa:%02x:%02x", i/256, i%256),
			IsEthernet:     true,
			Media:          "Ethernet autoselect",
			SupportedMedia: []string{"media autoselect"},
			Options:        []string{"RXCSUM", "TXCSUM", "VLAN_MTU", "VLAN_HWTAGGING", "VLAN_HWCSUM", "TSO4", "TSO6", "LRO", "LINKSTATE"},
			Capabilities:   []string{"RXCSUM", "TXCSUM", "VLAN_MTU", "VLAN_HWTAGGING", "JUMBO_MTU", "VLAN_HWCSUM", "TSO4", "TSO6", "LRO", "LINKSTATE"},
		}
		if drv != "vtnet" {
			ifc.Options = append(ifc.Options, "VLAN_HWFILTER")
			ifc.Capabilities = append(ifc.Capabilities, "VLAN_HWFILTER")
		}
		top := 10000
		if n.Speeds != nil {
			for _, sp := range n.Speeds {
				w := speedWord(sp)
				ifc.SupportedMedia = append(ifc.SupportedMedia, "media "+w+" mediaopt full-duplex")
				if sp <= 100 {
					ifc.SupportedMedia = append(ifc.SupportedMedia, "media "+w)
				}
				top = sp
			}
			top = n.Speeds[len(n.Speeds)-1]
		} else {
			ifc.SupportedMedia = append(ifc.SupportedMedia, "media 10Gbase-T mediaopt full-duplex")
		}
		if n.Link {
			ifc.Status = "active"
			ifc.MediaActive = speedWord(top) + " <full-duplex>"
		} else {
			ifc.Status = "no carrier"
			ifc.MediaActive = "autoselect"
		}
		s.add(ifc)
	}
	return s
}

// Lab returns the standard development lab: vtnet0..vtnet4 (virtio) plus
// two Intel NICs, so the UI shows both "n/a" and settable speed.
func Lab() *Sim {
	s := New(
		NIC{Name: "vtnet0", Link: true},
		NIC{Name: "vtnet1", Link: true},
		NIC{Name: "vtnet2", Link: true},
		NIC{Name: "vtnet3", Link: true},
		NIC{Name: "vtnet4", Link: true},
		NIC{Name: "igb0", Link: false, Speeds: []int{10, 100, 1000}},
		NIC{Name: "igb1", Link: true, Speeds: []int{10, 100, 1000}},
	)
	return s
}

func speedWord(sp int) string {
	switch {
	case sp == 10:
		return "10baseT/UTP"
	case sp == 100:
		return "100baseTX"
	case sp == 1000:
		return "1000baseT"
	case sp == 2500:
		return "2500Base-T"
	case sp >= 1000:
		return fmt.Sprintf("%dGbase-T", sp/1000)
	}
	return fmt.Sprintf("%dbaseT", sp)
}

func (s *Sim) add(i *state.Interface) {
	s.ifs[i.Name] = i
	s.order = append(s.order, i.Name)
	s.counters[i.Name] = &backend.Counters{}
}

func (s *Sim) remove(name string) {
	delete(s.ifs, name)
	delete(s.counters, name)
	for i, n := range s.order {
		if n == name {
			s.order = append(s.order[:i], s.order[i+1:]...)
			break
		}
	}
}

// SetLink changes the carrier of a simulated NIC.
func (s *Sim) SetLink(name string, up bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if i := s.ifs[name]; i != nil {
		if up {
			i.Status = "active"
			i.MediaActive = "10Gbase-T <full-duplex>"
		} else {
			i.Status = "no carrier"
		}
	}
}

// Learn adds a dynamic MAC entry as if a frame had been received.
func (s *Sim) Learn(bridge, mac string, vlan int, port string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.macs[bridge] = append(s.macs[bridge], state.MACEntry{MAC: mac, VLAN: vlan, Port: port, Expire: 300})
}

// File returns a file written via WriteFile.
func (s *Sim) File(path string) []byte {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.files[path]
}

// Commands returns a copy of the command log.
func (s *Sim) Commands() []string {
	s.mu.Lock()
	defer s.mu.Unlock()
	return append([]string(nil), s.Log...)
}

func (s *Sim) ResetLog() {
	s.mu.Lock()
	s.Log = nil
	s.mu.Unlock()
}

// ---- Backend implementation ------------------------------------------------

func (s *Sim) Snapshot(ctx context.Context) (*state.Snapshot, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	snap := &state.Snapshot{}
	for _, n := range s.order {
		c := clone(s.ifs[n])
		snap.Interfaces = append(snap.Interfaces, *c)
	}
	return snap, nil
}

func clone(i *state.Interface) *state.Interface {
	c := *i
	c.Flags = append([]string{}, i.Flags...)
	c.Options = append([]string{}, i.Options...)
	c.Capabilities = append([]string{}, i.Capabilities...)
	c.SupportedMedia = append([]string{}, i.SupportedMedia...)
	c.IPv4 = append([]string{}, i.IPv4...)
	c.IPv6 = append([]string{}, i.IPv6...)
	if i.Bridge != nil {
		b := *i.Bridge
		b.Flags = append([]string{}, i.Bridge.Flags...)
		b.Spans = append([]string{}, i.Bridge.Spans...)
		b.Members = nil
		for _, m := range i.Bridge.Members {
			mm := m
			mm.Flags = append([]string{}, m.Flags...)
			mm.Tagged = append(config.VIDSet{}, m.Tagged...)
			b.Members = append(b.Members, mm)
		}
		c.Bridge = &b
	}
	if i.Lagg != nil {
		l := *i.Lagg
		l.Ports = append([]state.LaggPort{}, i.Lagg.Ports...)
		c.Lagg = &l
	}
	return &c
}

func (s *Sim) MACTable(ctx context.Context, bridge string) ([]state.MACEntry, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.ifs[bridge]; !ok {
		return nil, fmt.Errorf("ifconfig: interface %s does not exist", bridge)
	}
	return append([]state.MACEntry{}, s.macs[bridge]...), nil
}

func (s *Sim) Counters(ctx context.Context) (map[string]backend.Counters, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := map[string]backend.Counters{}
	for n, c := range s.counters {
		i := s.ifs[n]
		if s.Traffic && i != nil && i.LinkUp() && i.AdminUp() && n != "lo0" {
			pk := uint64(rand.Intn(2000) + 50)
			c.RxPackets += pk
			c.RxBytes += pk * uint64(rand.Intn(1000)+200)
			pk = uint64(rand.Intn(2000) + 50)
			c.TxPackets += pk
			c.TxBytes += pk * uint64(rand.Intn(1000)+200)
			if rand.Intn(200) == 0 {
				c.RxErrors++
			}
		}
		cc := *c
		if i != nil {
			if i.LinkUp() {
				cc.LinkState = 2
			} else {
				cc.LinkState = 1
			}
			cc.Baudrate = uint64(i.SpeedMbps()) * 1000000
		}
		out[n] = cc
	}
	return out, nil
}

func (s *Sim) Routes(ctx context.Context) (backend.Routes, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.routes, nil
}

func (s *Sim) Sysctl(ctx context.Context, names ...string) (map[string]string, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := map[string]string{}
	for _, n := range names {
		if v, ok := s.sysctl[n]; ok {
			out[n] = v
		}
	}
	return out, nil
}

func (s *Sim) SysInfo(ctx context.Context) (backend.SysInfo, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return backend.SysInfo{
		Hostname: s.hostname, OSRelease: "15.1-RELEASE-p6 (simulated)", Machine: "amd64",
		UptimeSec: int64(time.Since(s.start).Seconds()), CPUModel: "Simulated CPU", NCPU: 4,
		CPUPercent: 3 + rand.Float64()*4, MemTotal: 4 << 30, MemUsed: 600 << 20, Load: [3]float64{0.1, 0.08, 0.05},
	}, nil
}

func (s *Sim) WriteFile(ctx context.Context, path string, data []byte) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.Log = append(s.Log, "# write "+path)
	s.files[path] = append([]byte(nil), data...)
	return nil
}

func (s *Sim) Run(ctx context.Context, op backend.Op) (string, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	cmd := op.String()
	s.Log = append(s.Log, cmd)
	if os.Getenv("BSDSWITCH_SIM_TRACE") != "" {
		fmt.Fprintln(os.Stderr, "sim:", cmd)
	}
	if s.FailOn != nil && s.FailOn.MatchString(cmd) {
		return "", fmt.Errorf("simulated failure: %s", cmd)
	}
	if s.OnRun != nil {
		s.OnRun(op)
	}
	if len(op.Argv) == 0 {
		return "", fmt.Errorf("empty command")
	}
	args := op.Argv[1:]
	switch op.Argv[0] {
	case "ifconfig", "/sbin/ifconfig":
		return "", s.ifconfig(args)
	case "sysctl", "/sbin/sysctl":
		for _, a := range args {
			k, v, ok := strings.Cut(a, "=")
			if !ok {
				return "", fmt.Errorf("sysctl: bad argument %q", a)
			}
			s.sysctl[k] = v
		}
		return "", nil
	case "route", "/sbin/route":
		return "", s.route(args)
	case "hostname", "/bin/hostname":
		if len(args) == 1 {
			s.hostname = args[0]
		}
		return "", nil
	case "dhclient":
		// simulate a DHCP lease
		name := args[len(args)-1]
		if i := s.ifs[name]; i != nil && len(i.IPv4) == 0 {
			n := 100 + len(s.order)
			if strings.Contains(name, ".") {
				i.IPv4 = append(i.IPv4, fmt.Sprintf("10.99.0.%d/24", n))
			} else {
				i.IPv4 = append(i.IPv4, fmt.Sprintf("192.168.1.%d/24", n))
				if s.routes.Default4 == "" {
					s.routes.Default4 = "192.168.1.1"
				}
			}
		}
		return "", nil
	default:
		// sysrc, service, pkill, tzsetup, ... are recorded only.
		return "", nil
	}
}

func (s *Sim) route(args []string) error {
	// route [-6] add|change|delete default [gw]
	v6 := false
	if len(args) > 0 && (args[0] == "-6" || args[0] == "-inet6") {
		v6 = true
		args = args[1:]
	}
	if len(args) < 2 || args[1] != "default" {
		return fmt.Errorf("route: unsupported %v", args)
	}
	cur := &s.routes.Default4
	if v6 {
		cur = &s.routes.Default6
	}
	switch args[0] {
	case "add":
		if *cur != "" {
			return fmt.Errorf("route: writing to routing socket: File exists")
		}
		*cur = args[2]
	case "change":
		if *cur == "" {
			return fmt.Errorf("route: writing to routing socket: No such process")
		}
		*cur = args[2]
	case "delete":
		if *cur == "" {
			return fmt.Errorf("route: writing to routing socket: No such process")
		}
		*cur = ""
	default:
		return fmt.Errorf("route: unsupported %v", args)
	}
	return nil
}

func atoi(s string) (int, error) {
	n, err := strconv.Atoi(s)
	if err != nil {
		return 0, fmt.Errorf("ifconfig: invalid value %q", s)
	}
	return n, nil
}

func (s *Sim) ifconfig(args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("ifconfig: missing interface")
	}
	name := args[0]
	args = args[1:]
	if len(args) > 0 && args[0] == "create" {
		if _, ok := s.ifs[name]; ok {
			return fmt.Errorf("ifconfig: SIOCIFCREATE2 (%s): File exists", name)
		}
		switch {
		case regexp.MustCompile(`^bridge\d+$`).MatchString(name):
			s.add(&state.Interface{Name: name, Driver: "bridge", MTU: 1500, Cloned: true, IsEthernet: true,
				Flags: []string{"BROADCAST", "SIMPLEX", "MULTICAST"}, MAC: "58:9c:fc:10:ff:b6",
				Bridge: &state.Bridge{ID: "58:9c:fc:10:ff:b6", Priority: 32768, HelloTime: 2, FwdDelay: 15,
					MaxAge: 20, HoldCount: 6, Proto: "rstp", MaxAddr: 2000, Timeout: 1200,
					RootID: "58:9c:fc:10:ff:b6", RootPriority: 32768, Flags: []string{}}})
		case regexp.MustCompile(`^[a-z]+\d+\.\d+$`).MatchString(name):
			parent, tag, _ := strings.Cut(name, ".")
			p, ok := s.ifs[parent]
			if !ok {
				return fmt.Errorf("ifconfig: SIOCIFCREATE2 (%s): Invalid argument", name)
			}
			t, _ := strconv.Atoi(tag)
			s.add(&state.Interface{Name: name, Driver: "vlan", MTU: p.MTU, Cloned: true, IsEthernet: true,
				Flags: []string{"BROADCAST", "SIMPLEX", "MULTICAST"}, MAC: p.MAC, VLANTag: t, VLANParent: parent, Status: "active"})
		case regexp.MustCompile(`^lagg\d+$`).MatchString(name):
			s.add(&state.Interface{Name: name, Driver: "lagg", MTU: 1500, Cloned: true, IsEthernet: true,
				Flags: []string{"BROADCAST", "SIMPLEX", "MULTICAST"}, MAC: "bc:24:11:ff:00:00",
				Lagg: &state.Lagg{Proto: "failover"}, Status: "no carrier"})
		default:
			return fmt.Errorf("ifconfig: SIOCIFCREATE2 (%s): Invalid argument", name)
		}
		args = args[1:]
	}
	ifc, ok := s.ifs[name]
	if !ok {
		return fmt.Errorf("ifconfig: interface %s does not exist", name)
	}
	for len(args) > 0 {
		a := args[0]
		args = args[1:]
		need := func(n int) ([]string, error) {
			if len(args) < n {
				return nil, fmt.Errorf("ifconfig: %s: missing argument", a)
			}
			v := args[:n]
			args = args[n:]
			return v, nil
		}
		var err error
		switch a {
		case "destroy":
			if ifc.Bridge != nil {
				for _, m := range ifc.Bridge.Members {
					s.unpromisc(m.Name)
				}
			}
			if ifc.Lagg != nil {
				for _, p := range ifc.Lagg.Ports {
					delete(s.laggMember, p.Name)
				}
			}
			s.remove(name)
			delete(s.macs, name)
			return nil
		case "up":
			setFlag(ifc, "UP", true)
			if ifc.Bridge != nil || ifc.VLANParent != "" || ifc.Lagg != nil {
				setFlag(ifc, "RUNNING", true)
			}
		case "down":
			setFlag(ifc, "UP", false)
		case "mtu":
			v, e := need(1)
			if e != nil {
				return e
			}
			n, e := atoi(v[0])
			if e != nil {
				return e
			}
			if n > 1500 && !ifc.HasCap("JUMBO_MTU") && ifc.Bridge == nil {
				return fmt.Errorf("ifconfig: ioctl SIOCSIFMTU (set mtu): Invalid argument")
			}
			ifc.MTU = n
			if ifc.Bridge != nil {
				for _, m := range ifc.Bridge.Members {
					s.ifs[m.Name].MTU = n
				}
			}
		case "description":
			v, e := need(1)
			if e != nil {
				return e
			}
			ifc.Description = v[0]
		case "-description":
			ifc.Description = ""
		case "-lro", "-tso", "-vlanhwfilter", "-txcsum", "-rxcsum", "-vlanhwtag":
			opt := map[string][]string{"-lro": {"LRO"}, "-tso": {"TSO4", "TSO6"}, "-vlanhwfilter": {"VLAN_HWFILTER"},
				"-txcsum": {"TXCSUM"}, "-rxcsum": {"RXCSUM"}, "-vlanhwtag": {"VLAN_HWTAGGING"}}[a]
			ifc.Options = without(ifc.Options, opt...)
		case "lro", "tso", "vlanhwfilter":
			opt := map[string][]string{"lro": {"LRO"}, "tso": {"TSO4", "TSO6"}, "vlanhwfilter": {"VLAN_HWFILTER"}}[a]
			for _, o := range opt {
				if ifc.HasCap(o) && !ifc.HasOption(o) {
					ifc.Options = append(ifc.Options, o)
				}
			}
		case "media":
			v, e := need(1)
			if e != nil {
				return e
			}
			opt := ""
			if len(args) >= 2 && args[0] == "mediaopt" {
				opt = args[1]
				args = args[2:]
			}
			want := "media " + v[0]
			if opt != "" {
				want += " mediaopt " + opt
			}
			found := false
			for _, m := range ifc.SupportedMedia {
				if m == want {
					found = true
				}
			}
			if !found {
				return fmt.Errorf("ifconfig: SIOCSIFMEDIA (media): Device not configured")
			}
			if v[0] == "autoselect" {
				ifc.Media = "Ethernet autoselect"
				if ifc.LinkUp() {
					ifc.MediaActive = speedWord(maxSpeed(ifc)) + " <full-duplex>"
				}
			} else {
				d := ""
				if opt != "" {
					d = " <" + opt + ">"
				}
				ifc.Media = "Ethernet " + v[0] + d
				ifc.MediaActive = v[0] + d
			}
		case "inet", "inet6":
			v, e := need(1)
			if e != nil {
				return e
			}
			list := &ifc.IPv4
			if a == "inet6" {
				list = &ifc.IPv6
			}
			mode := "alias"
			if len(args) > 0 && (args[0] == "alias" || args[0] == "-alias" || args[0] == "delete") {
				mode = args[0]
				args = args[1:]
			}
			isFlag := func(w string) bool {
				switch w {
				case "accept_rtadv", "-accept_rtadv", "ifdisabled", "-ifdisabled", "auto_linklocal", "-auto_linklocal":
					return true
				}
				return false
			}
			if isFlag(v[0]) {
				for len(args) > 0 && isFlag(args[0]) {
					args = args[1:]
				}
				continue
			}
			if mode == "alias" {
				if !contains(*list, v[0]) {
					*list = append(*list, v[0])
				}
			} else {
				if !contains(*list, v[0]) {
					return fmt.Errorf("ifconfig: ioctl (SIOCDIFADDR): Can't assign requested address")
				}
				*list = without(*list, v[0])
			}
		default:
			if ifc.Bridge != nil {
				args, err = s.bridgeCmd(ifc, a, args)
			} else if ifc.Lagg != nil {
				args, err = s.laggCmd(ifc, a, args)
			} else {
				err = fmt.Errorf("ifconfig: %s: bad value", a)
			}
			if err != nil {
				return err
			}
		}
	}
	return nil
}

func maxSpeed(i *state.Interface) int {
	m := 0
	for _, s := range i.SupportedMedia {
		if v := state.MediaSpeed(s); v > m {
			m = v
		}
	}
	if m == 0 {
		return 10000
	}
	return m
}

func (s *Sim) unpromisc(name string) {
	if m := s.ifs[name]; m != nil {
		setFlag(m, "PROMISC", false)
	}
}

func (s *Sim) member(b *state.Interface, name string) (*state.Member, error) {
	if m := b.Bridge.Member(name); m != nil {
		return m, nil
	}
	return nil, fmt.Errorf("ifconfig: %s is not a member of %s", name, b.Name)
}

func (s *Sim) bridgeCmd(b *state.Interface, a string, args []string) ([]string, error) {
	br := b.Bridge
	need := func(n int) ([]string, error) {
		if len(args) < n {
			return nil, fmt.Errorf("ifconfig: %s: missing argument", a)
		}
		v := args[:n]
		args = args[n:]
		return v, nil
	}
	memberArg := func() (*state.Member, error) {
		v, err := need(1)
		if err != nil {
			return nil, err
		}
		return s.member(b, v[0])
	}
	flag := func(f string, on bool) error {
		m, err := memberArg()
		if err != nil {
			return err
		}
		if on {
			if !m.Has(f) {
				m.Flags = append(m.Flags, f)
			}
		} else {
			m.Flags = without(m.Flags, f)
		}
		if f == "STP" {
			s.updateSTP(b)
		}
		return nil
	}
	intArg := func() (int, error) {
		v, err := need(1)
		if err != nil {
			return 0, err
		}
		return atoi(v[0])
	}
	var err error
	switch a {
	case "vlanfilter":
		if !contains(br.Flags, "VLANFILTER") {
			br.Flags = append(br.Flags, "VLANFILTER")
		}
	case "-vlanfilter":
		br.Flags = without(br.Flags, "VLANFILTER")
	case "addm":
		v, e := need(1)
		if e != nil {
			return args, e
		}
		mi, ok := s.ifs[v[0]]
		if !ok {
			return args, fmt.Errorf("ifconfig: BRDGADD %s: No such file or directory", v[0])
		}
		if br.Member(v[0]) != nil {
			return args, fmt.Errorf("ifconfig: BRDGADD %s: File exists", v[0])
		}
		if len(mi.IPv4) > 0 {
			return args, fmt.Errorf("ifconfig: BRDGADD %s: Invalid argument (member has IP address)", v[0])
		}
		if s.laggMember[v[0]] != "" {
			return args, fmt.Errorf("ifconfig: BRDGADD %s: Device busy", v[0])
		}
		m := state.Member{Name: v[0], Flags: []string{"LEARNING", "DISCOVER", "AUTOEDGE", "AUTOPTP"},
			PortNo: len(s.order), Priority: 128, PathCost: 2000, Untagged: br.DefUntagged, Tagged: config.VIDSet{}}
		if len(br.Members) == 0 {
			b.MTU = mi.MTU
		} else {
			mi.MTU = b.MTU
		}
		mi.Options = without(mi.Options, "LRO")
		setFlag(mi, "PROMISC", true)
		for len(args) >= 2 && (args[0] == "untagged" || args[0] == "tagged") {
			if args[0] == "untagged" {
				n, e := atoi(args[1])
				if e != nil {
					return args, e
				}
				m.Untagged = n
			} else {
				t, e := config.ParseVIDSet(args[1])
				if e != nil {
					return args, fmt.Errorf("ifconfig: invalid vlan list %q", args[1])
				}
				m.Tagged = t
			}
			args = args[2:]
		}
		br.Members = append(br.Members, m)
	case "deletem":
		v, e := need(1)
		if e != nil {
			return args, e
		}
		if _, e := s.member(b, v[0]); e != nil {
			return args, e
		}
		var mem []state.Member
		for _, m := range br.Members {
			if m.Name != v[0] {
				mem = append(mem, m)
			}
		}
		br.Members = mem
		s.unpromisc(v[0])
		var keep []state.MACEntry
		for _, e := range s.macs[b.Name] {
			if e.Port != v[0] {
				keep = append(keep, e)
			}
		}
		s.macs[b.Name] = keep
	case "ifuntagged":
		m, e := memberArg()
		if e != nil {
			return args, e
		}
		n, e := intArg()
		if e != nil {
			return args, e
		}
		if n < 1 || n > 4094 {
			return args, fmt.Errorf("ifconfig: invalid vlan id %d", n)
		}
		m.Untagged = n
	case "-ifuntagged":
		m, e := memberArg()
		if e != nil {
			return args, e
		}
		m.Untagged = 0
	case "iftagged", "+iftagged", "-iftagged":
		m, e := memberArg()
		if e != nil {
			return args, e
		}
		v, e := need(1)
		if e != nil {
			return args, e
		}
		set, e := config.ParseVIDSet(v[0])
		if e != nil {
			return args, fmt.Errorf("ifconfig: invalid vlan list %q", v[0])
		}
		switch a {
		case "iftagged":
			m.Tagged = set
		case "+iftagged":
			m.Tagged = append(m.Tagged, set...).Normalize()
		case "-iftagged":
			m.Tagged = m.Tagged.Minus(set)
		}
	case "stp":
		err = flag("STP", true)
	case "-stp":
		err = flag("STP", false)
	case "edge":
		err = flag("EDGE", true)
	case "-edge":
		err = flag("EDGE", false)
	case "autoedge":
		err = flag("AUTOEDGE", true)
	case "-autoedge":
		err = flag("AUTOEDGE", false)
	case "ptp":
		err = flag("PTP", true)
	case "-ptp":
		err = flag("PTP", false)
	case "autoptp":
		err = flag("AUTOPTP", true)
	case "-autoptp":
		err = flag("AUTOPTP", false)
	case "private":
		err = flag("PRIVATE", true)
	case "-private":
		err = flag("PRIVATE", false)
	case "sticky":
		err = flag("STICKY", true)
	case "-sticky":
		err = flag("STICKY", false)
	case "qinq":
		err = flag("QINQ", true)
	case "-qinq":
		err = flag("QINQ", false)
	case "learn":
		err = flag("LEARNING", true)
	case "-learn":
		err = flag("LEARNING", false)
	case "discover":
		err = flag("DISCOVER", true)
	case "-discover":
		err = flag("DISCOVER", false)
	case "ifvlanproto":
		m, e := memberArg()
		if e != nil {
			return args, e
		}
		v, e := need(1)
		if e != nil {
			return args, e
		}
		if v[0] != "802.1q" && v[0] != "802.1ad" {
			return args, fmt.Errorf("ifconfig: invalid vlan protocol %q", v[0])
		}
		if v[0] == "802.1q" {
			m.VLANProto = ""
		} else {
			m.VLANProto = v[0]
		}
	case "span":
		v, e := need(1)
		if e != nil {
			return args, e
		}
		if _, ok := s.ifs[v[0]]; !ok {
			return args, fmt.Errorf("ifconfig: BRDGADDS %s: No such file or directory", v[0])
		}
		if !contains(br.Spans, v[0]) {
			br.Spans = append(br.Spans, v[0])
		}
	case "-span":
		v, e := need(1)
		if e != nil {
			return args, e
		}
		if !contains(br.Spans, v[0]) {
			return args, fmt.Errorf("ifconfig: BRDGDELS %s: No such file or directory", v[0])
		}
		br.Spans = without(br.Spans, v[0])
	case "ifpriority":
		m, e := memberArg()
		if e != nil {
			return args, e
		}
		n, e := intArg()
		if e != nil {
			return args, e
		}
		if n < 0 || n > 240 {
			return args, fmt.Errorf("ifconfig: BRDGSIFPRIO: Invalid argument")
		}
		m.Priority = n
	case "ifpathcost":
		m, e := memberArg()
		if e != nil {
			return args, e
		}
		n, e := intArg()
		if e != nil {
			return args, e
		}
		if n == 0 {
			n = 2000
		}
		m.PathCost = n
	case "ifmaxaddr":
		m, e := memberArg()
		if e != nil {
			return args, e
		}
		n, e := intArg()
		if e != nil {
			return args, e
		}
		m.IfMaxAddr = n
	case "timeout", "maxaddr", "priority", "hellotime", "maxage", "fwddelay", "holdcnt":
		n, e := intArg()
		if e != nil {
			return args, e
		}
		switch a {
		case "timeout":
			br.Timeout = n
		case "maxaddr":
			br.MaxAddr = n
		case "priority":
			if n < 0 || n > 61440 {
				return args, fmt.Errorf("ifconfig: BRDGSPRI: Invalid argument")
			}
			br.Priority = n
			br.RootPriority = n
		case "hellotime":
			br.HelloTime = n
		case "maxage":
			br.MaxAge = n
		case "fwddelay":
			br.FwdDelay = n
		case "holdcnt":
			br.HoldCount = n
		}
	case "proto":
		v, e := need(1)
		if e != nil {
			return args, e
		}
		if v[0] != "stp" && v[0] != "rstp" {
			return args, fmt.Errorf("ifconfig: unknown stp protocol")
		}
		br.Proto = v[0]
		s.updateSTP(b)
	case "static":
		v, e := need(2)
		if e != nil {
			return args, e
		}
		if _, e := s.member(b, v[0]); e != nil {
			return args, e
		}
		vlan := 0
		if len(args) >= 2 && args[0] == "vlan" {
			vlan, _ = strconv.Atoi(args[1])
			args = args[2:]
		}
		mac := strings.ToLower(v[1])
		var keep []state.MACEntry
		for _, e := range s.macs[b.Name] {
			if !(e.MAC == mac && e.VLAN == vlan) {
				keep = append(keep, e)
			}
		}
		s.macs[b.Name] = append(keep, state.MACEntry{MAC: mac, VLAN: vlan, Port: v[0], Static: true})
	case "deladdr":
		v, e := need(1)
		if e != nil {
			return args, e
		}
		vlan := 0
		if len(args) >= 2 && args[0] == "vlan" {
			vlan, _ = strconv.Atoi(args[1])
			args = args[2:]
		}
		found := false
		var keep []state.MACEntry
		for _, e := range s.macs[b.Name] {
			if e.MAC == strings.ToLower(v[0]) && e.VLAN == vlan {
				found = true
				continue
			}
			keep = append(keep, e)
		}
		if !found {
			return args, fmt.Errorf("ifconfig: BRDGDADDR %s: No such file or directory", v[0])
		}
		s.macs[b.Name] = keep
	case "flush":
		var keep []state.MACEntry
		for _, e := range s.macs[b.Name] {
			if e.Static {
				keep = append(keep, e)
			}
		}
		s.macs[b.Name] = keep
	case "flushall":
		s.macs[b.Name] = nil
	default:
		return args, fmt.Errorf("ifconfig: %s: bad value", a)
	}
	return args, err
}

// updateSTP simulates converged spanning-tree port states.
func (s *Sim) updateSTP(b *state.Interface) {
	for i := range b.Bridge.Members {
		m := &b.Bridge.Members[i]
		if m.Has("STP") {
			m.Proto = b.Bridge.Proto
			m.Role = "designated"
			m.State = "forwarding"
		} else {
			m.Proto, m.Role, m.State = "", "", ""
		}
	}
}

func setFlag(i *state.Interface, f string, on bool) {
	if on {
		if !i.HasFlag(f) {
			i.Flags = append(i.Flags, f)
		}
	} else {
		i.Flags = without(i.Flags, f)
	}
}

func without(l []string, rm ...string) []string {
	out := []string{}
	for _, x := range l {
		if !contains(rm, x) {
			out = append(out, x)
		}
	}
	return out
}

func contains(l []string, s string) bool {
	for _, x := range l {
		if x == s {
			return true
		}
	}
	return false
}

// SortedNames returns interface names (for tests).
func (s *Sim) SortedNames() []string {
	s.mu.Lock()
	defer s.mu.Unlock()
	n := append([]string{}, s.order...)
	sort.Strings(n)
	return n
}

func (s *Sim) laggCmd(l *state.Interface, a string, args []string) ([]string, error) {
	need := func(n int) ([]string, error) {
		if len(args) < n {
			return nil, fmt.Errorf("ifconfig: %s: missing argument", a)
		}
		v := args[:n]
		args = args[n:]
		return v, nil
	}
	switch a {
	case "laggproto":
		v, e := need(1)
		if e != nil {
			return args, e
		}
		switch v[0] {
		case "lacp", "failover", "loadbalance", "roundrobin", "broadcast", "none":
		default:
			return args, fmt.Errorf("ifconfig: invalid lagg protocol %q", v[0])
		}
		l.Lagg.Proto = v[0]
	case "lagghash":
		v, e := need(1)
		if e != nil {
			return args, e
		}
		l.Lagg.Hash = v[0]
	case "lacp_fast_timeout", "-lacp_fast_timeout", "lacp_strict", "-lacp_strict":
	case "laggport":
		v, e := need(1)
		if e != nil {
			return args, e
		}
		p, ok := s.ifs[v[0]]
		if !ok {
			return args, fmt.Errorf("ifconfig: SIOCSLAGGPORT: No such file or directory")
		}
		if s.laggMember[v[0]] != "" {
			return args, fmt.Errorf("ifconfig: SIOCSLAGGPORT: Device busy")
		}
		s.laggMember[v[0]] = l.Name
		flags := []string{"ACTIVE"}
		if p.LinkUp() {
			flags = append(flags, "COLLECTING", "DISTRIBUTING")
			l.Status = "active"
			l.MediaActive = p.MediaActive
		}
		l.Lagg.Ports = append(l.Lagg.Ports, state.LaggPort{Name: v[0], Flags: flags})
		p.MTU = l.MTU
	case "-laggport":
		v, e := need(1)
		if e != nil {
			return args, e
		}
		if s.laggMember[v[0]] != l.Name {
			return args, fmt.Errorf("ifconfig: SIOCSLAGGDELPORT: No such file or directory")
		}
		delete(s.laggMember, v[0])
		var keep []state.LaggPort
		for _, p := range l.Lagg.Ports {
			if p.Name != v[0] {
				keep = append(keep, p)
			}
		}
		l.Lagg.Ports = keep
	default:
		return args, fmt.Errorf("ifconfig: %s: bad value", a)
	}
	return args, nil
}
